import{_ as o,o as r,c as s,a2 as e}from"./chunks/framework.BWuWLRhz.js";const _=JSON.parse('{"title":"検索履歴","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/history.md","filePath":"ja-JP/user-guide/settings/history.md","lastUpdated":1789222057000}'),n={name:"ja-JP/user-guide/settings/history.md"};function i(a,t,l,g,d,c){return r(),s("div",null,[...t[0]||(t[0]=[e('<h1 id="検索履歴" tabindex="-1">検索履歴 <a class="header-anchor" href="#検索履歴" aria-label="Permalink to &quot;検索履歴&quot;">​</a></h1><p>履歴設定画面では、Lertaro の利用履歴と関連付けによる優先表示を管理します。画面上部には <strong>検索履歴</strong> と <strong>キーワード履歴</strong> の 2 つのタブが配置されています。</p><h2 id="_1-検索履歴-search-history" tabindex="-1">1. 検索履歴（Search History） <a class="header-anchor" href="#_1-検索履歴-search-history" aria-label="Permalink to &quot;1. 検索履歴（Search History）&quot;">​</a></h2><p>検索結果から実際に起動したアイテムと、そのときに使用した検索クエリを紐付けて記憶します。</p><ul><li><strong>スマート優先表示</strong>：過去の検索クエリと類似するキーワードを入力した際、以前開いたアイテムが結果一覧の上位に自動的に優先表示されます（例: <code>bcomp</code> で <code>BCompare.exe</code> を起動したことがある場合、次回 <code>bc</code> と入力しても上位に表示）。</li><li><strong>使用状況に基づく並び順</strong>：履歴候補は、マッチの開始位置、使用回数の降順、最後に開いた時刻の降順、あいまい一致の重みの順で並びます。この規則は履歴候補だけに適用され、他の結果カテゴリの並び順は変わりません。</li><li><strong>インラインウィンドウでの自動分類</strong>：ファイルダイアログのインライン検索時、現在のフォルダー内の一致項目は「現在のフォルダー」、それ以外は「全体検索」に自動分類されます。</li><li><strong>無効パスの自動除外</strong>：ファイルが削除または移動された場合、存在しないリンクは検索結果から自動的に除外され、重複表示も防がれます。</li><li><strong>管理操作</strong>： <ul><li><strong>履歴を有効化</strong>：記録機能の全体スイッチ。無効にしても既存の記録は保持されます。新しい項目は追加されませんが、既存の項目を開くと使用回数は引き続き加算されます。</li><li><strong>検索絞り込み</strong>：上部の検索バーで履歴項目を絞り込み。</li><li><strong>使用回数と削除</strong>：各項目には開いた回数が表示されます。回数のしきい値を選び、<strong>N 回以下をクリア</strong> を押すと使用頻度の低い項目を削除できます。個別削除や<strong>すべての履歴を消去</strong>も利用できます。</li><li><strong>リアルタイム更新</strong>：別の検索ウィンドウで新しい項目を開くと、一覧の使用回数が自動更新されます。</li></ul></li></ul><h2 id="_2-キーワード履歴-keyword-history" tabindex="-1">2. キーワード履歴（Keyword History） <a class="header-anchor" href="#_2-キーワード履歴-keyword-history" aria-label="Permalink to &quot;2. キーワード履歴（Keyword History）&quot;">​</a></h2><p>結果やアクションを実行したとき、またはその検索語でメインウィンドウを開いたときに実際に使用された <strong>検索文字列そのもの</strong> を記憶します。入力しただけでクイック検索ウィンドウを閉じたり、フォーカスを失ったりした場合は追加されません。</p><ul><li><strong>ホットキーによる履歴呼び出し</strong>：クイックウィンドウで <strong><code>Alt+Up</code></strong>（前へ）/ <strong><code>Alt+Down</code></strong>（次へ）を押して過去の検索語を順に呼び出せます。<strong><code>Ctrl+Delete</code></strong> で現在表示中の履歴語を削除できます。</li><li><strong>使用回数と削除</strong>：各キーワードには使用回数が表示されます。回数のしきい値を選び、<strong>N 回以下をクリア</strong> を押すと使用頻度の低いキーワードを削除できます。</li><li><strong>個別管理</strong>：検索履歴と同様に <strong>履歴を有効化</strong> スイッチ、絞り込み、個別削除、<strong>すべての履歴を消去</strong> ボタンが用意されています。無効時も既存のキーワードの使用回数は加算されますが、新しいキーワードは追加されません。</li></ul>',8)])])}const u=o(n,[["render",i]]);export{_ as __pageData,u as default};
